import json
from pathlib import Path

def extract(path):
    users=[]; lasts=[]
    with open(path) as f:
        for line in f:
            try: o=json.loads(line)
            except: continue
            role=o.get("role") or o.get("type") or ""
            if "message" in o:
                m=o["message"]; role=m.get("role",role); content=m.get("content","")
            else:
                content=o.get("content") or o.get("text") or ""
            if isinstance(content, list):
                parts=[]
                for c in content:
                    if isinstance(c, dict) and c.get("type")=="text":
                        parts.append(c.get("text",""))
                    elif isinstance(c,str):
                        parts.append(c)
                content="\n".join(parts)
            if not isinstance(content,str):
                content=str(content)
            if role in ("user","human") or o.get("type")=="user":
                if "<user_query>" in content or content.strip():
                    # extract user_query body
                    import re
                    m=re.search(r"<user_query>\s*(.*?)\s*</user_query>", content, re.S)
                    u=m.group(1).strip() if m else content.strip()
                    if u and not u.startswith("Available") and "subagent" not in u[:40]:
                        users.append(u[:250].replace("\n"," "))
            if role in ("assistant","ai") or o.get("type")=="assistant":
                if len(content)>80:
                    lasts.append(content[:400].replace("\n"," "))
    return users, lasts

base=Path.home()/".dc-platform/memory/mirrors/agent-transcripts/new-mac"
for name in ["29597106-5b23-4b99-977d-cc9b58aebb60","c4eb3437-39d0-4c60-9825-92e6a81af0b4","2d913d63-f33d-4b5a-8d44-b71f52ccfa99","8be7c202-360e-4dd2-8ce1-38226b138e5a"]:
    p=base/name/f"{name}.jsonl"
    if not p.exists():
        # try find
        cands=list((base/name).rglob("*.jsonl"))
        p=cands[0] if cands else None
    if not p: 
        print("MISS", name); continue
    users, lasts = extract(p)
    print("====", name, "users", len(users), "size", p.stat().st_size)
    for u in users[-12:]:
        print("U:", u[:220])
    print("LAST A:")
    for a in lasts[-4:]:
        print("A:", a[:280])
    print()
